         Assert.AreEqual(150m, calc.CalculateDiscount(1000m));
     }

     [TestMethod]
     public void CalculateDiscount_JustBelow1000_Returns10Percent()
     {
         var calc = new DiscountCalculator();
         Assert.AreEqual(99.9m, calc.CalculateDiscount(999m));
     }

     [TestMethod]
     public void CalculateDiscount_Exactly500_Returns10Percent()
     {
         var calc = new DiscountCalculator();
         Assert.AreEqual(50m, calc.CalculateDiscount(500m));
     }

     [TestMethod]
     public void CalculateDiscount_JustBelow500_Returns5Percent()
     {
         var calc = new DiscountCalculator();
         Assert.AreEqual(24.95m, calc.CalculateDiscount(499m));
     }

     [TestMethod]
     public void CalculateDiscount_Exactly100_Returns5Percent()
     {
         var calc = new DiscountCalculator();
         Assert.AreEqual(5m, calc.CalculateDiscount(100m));
     }

     [TestMethod]
     public void CalculateDiscount_JustBelow100_ReturnsZero()
     {
         var calc = new DiscountCalculator();
         Assert.AreEqual(0m, calc.CalculateDiscount(99m));
     }

     [TestMethod]
     public void CalculateDiscount_Zero_ReturnsZero()
     {
         var calc = new DiscountCalculator();
         Assert.AreEqual(0m, calc.CalculateDiscount(0m));
     }

     // -- CalculateShipping tests --
     // Tests free shipping for a large order, but never tests the boundary at 250.
     // Does not test heavy item fee boundary at 10kg.
     // Does not test the express surcharge.

     [TestMethod]
     public void CalculateShipping_LargeOrder_FreeShipping()
     {
         var calc = new DiscountCalculator();
         var cost = calc.CalculateShipping(500m, 2.0, false);
         Assert.AreEqual(0m, cost);
     }

     [TestMethod]
     public void CalculateShipping_SmallOrder_ReturnsBaseCost()
     {
         var calc = new DiscountCalculator();
         var cost = calc.CalculateShipping(50m, 2.0, false);
         Assert.AreEqual(6.00m, cost);
     }

     [TestMethod]
     public void CalculateShipping_ZeroWeight_Throws()
     {
         var calc = new DiscountCalculator();
         Assert.ThrowsExactly<ArgumentOutOfRangeException>(
             () => calc.CalculateShipping(50m, 0, false));
     }

     // -- CalculateShipping boundary & feature tests --

     [TestMethod]
     public void CalculateShipping_Exactly250_ReturnsShippingCost()
     {
         var calc = new DiscountCalculator();
         var cost = calc.CalculateShipping(250m, 2.0, false);
         Assert.AreEqual(6.00m, cost);
     }

     [TestMethod]
     public void CalculateShipping_JustAbove250_FreeShipping()
     {
         var calc = new DiscountCalculator();
         Assert.AreEqual(0m, calc.CalculateShipping(250.01m, 2.0, false));
     }

     [TestMethod]
     public void CalculateShipping_HeavyItem_AddsHeavyFee()
     {
         var calc = new DiscountCalculator();
         // base = 5 + 11*0.50 = 10.50, + 15 heavy fee = 25.50
         Assert.AreEqual(25.50m, calc.CalculateShipping(50m, 11.0, false));
     }

     [TestMethod]
     public void CalculateShipping_Exactly10kg_NoHeavyFee()
     {
         var calc = new DiscountCalculator();
         // base = 5 + 10*0.50 = 10.00, no heavy fee
         Assert.AreEqual(10.00m, calc.CalculateShipping(50m, 10.0, false));
     }

     [TestMethod]
     public void CalculateShipping_Express_Adds50PercentSurcharge()
     {
         var calc = new DiscountCalculator();
         // base = 5 + 2*0.50 = 6.00, express = 6 * 1.5 = 9.00
         Assert.AreEqual(9.00m, calc.CalculateShipping(50m, 2.0, true));
     }

     [TestMethod]
     public void CalculateShipping_HeavyExpress_BothApply()
     {
         var calc = new DiscountCalculator();
         // base = 5 + 11*0.50 = 10.50, + 15 = 25.50, * 1.5 = 38.25
         Assert.AreEqual(38.25m, calc.CalculateShipping(50m, 11.0, true));
     }

     [TestMethod]
     public void CalculateShipping_NegativeTotal_Throws()
     {
         var calc = new DiscountCalculator();
         Assert.ThrowsExactly<ArgumentOutOfRangeException>(
             () => calc.CalculateShipping(-1m, 2.0, false));
     }

     // -- ApplyCoupon boundary & feature tests --
     // Tests a percentage coupon but not the minimum floor (total can't go below 1.00).
     // Does not test unknown coupon codes returning zero discount.

     [TestMethod]
     public void ApplyCoupon_Save10_Applies10Percent()
     {
         var calc = new DiscountCalculator();
         var result = calc.ApplyCoupon(100m, "SAVE10");
         Assert.AreEqual(90m, result);
     }

     [TestMethod]
     public void ApplyCoupon_Flat50_SubtractsFifty()
     {
         var calc = new DiscountCalculator();
         var result = calc.ApplyCoupon(200m, "FLAT50");
         Assert.AreEqual(150m, result);
     }

     [TestMethod]
     public void ApplyCoupon_NullCoupon_Throws()
     {
         var calc = new DiscountCalculator();
         Assert.ThrowsExactly<ArgumentNullException>(
             () => calc.ApplyCoupon(100m, null!));
     }

     [TestMethod]
     public void ApplyCoupon_UnknownCode_ReturnsOriginalTotal()
     {
         var calc = new DiscountCalculator();
         Assert.AreEqual(100m, calc.ApplyCoupon(100m, "BOGUS"));
     }

     [TestMethod]
     public void ApplyCoupon_Save20_Applies20Percent()
     {
         var calc = new DiscountCalculator();
         Assert.AreEqual(80m, calc.ApplyCoupon(100m, "SAVE20"));
     }

     [TestMethod]
     public void ApplyCoupon_Flat5_SubtractsFive()
     {
         var calc = new DiscountCalculator();
         Assert.AreEqual(95m, calc.ApplyCoupon(100m, "FLAT5"));
     }

     [TestMethod]
     public void ApplyCoupon_MinimumFloor_CannotGoBelowOne()
     {
         var calc = new DiscountCalculator();
         // 2.00 - 50.00 = -48, should clamp to 1.00
         Assert.AreEqual(1.00m, calc.ApplyCoupon(2m, "FLAT50"));
     }

     [TestMethod]
     public void ApplyCoupon_ExactlyAtFloor_ReturnsOne()
     {
         var calc = new DiscountCalculator();
         // 5.00 * 0.80 = 4.00 with SAVE20; but let's use FLAT50 on 51 => 1.00
         Assert.AreEqual(1.00m, calc.ApplyCoupon(51m, "FLAT50"));
     }

     [TestMethod]
     public void ApplyCoupon_LowercaseCode_StillWorks()
     {
         var calc = new DiscountCalculator();
         Assert.AreEqual(90m, calc.ApplyCoupon(100m, "save10"));
     }
 }

